custom_css:
/* MoodTube theme: Green Terminal. A phosphor-green console: dashed frame, shell prompts, bracket buttons, a dot-matrix cover and an ASCII cat that blinks while music plays. */
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;700&family=VT323&family=Silkscreen:wght@700&display=swap');

.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal, #moodtube-dock {
  --t-bg: #050b07;
  --t-bg2: #0b2415;
  --t-g: #3dff7a;
  --t-g2: #8fffb0;
  --t-gd: #1d7a3d;
  --t-gdim: rgba(61, 255, 122, 0.6);
  --t-line: rgba(61, 255, 122, 0.45);
  --t-line2: rgba(61, 255, 122, 0.16);
  --t-dark: #04140a;
  --mt-bg-primary: var(--t-bg);
  --mt-bg-secondary: #08170e;
  --mt-bg-input: var(--t-bg2);
  --mt-accent: var(--t-g);
  --mt-accent-hover: var(--t-g2);
  --mt-border: var(--t-line);
  --mt-text: var(--t-g);
  --mt-text-dim: var(--t-gdim);
  --mt-text-on-accent: var(--t-dark);
  --mt-text-strong: var(--t-g2);
  --mt-divider: var(--t-line2);
  --mt-overlay: rgba(2, 6, 3, 0.85);
  --mt-modal-shadow: 0 0 24px rgba(61, 255, 122, 0.18);
  --mt-pl-spotify-tab: var(--t-g);
  --mt-pl-spotify-tab-text: var(--t-dark);
}

.mt-progress {
  --mt-slider-track: rgba(61, 255, 122, 0.18);
  --mt-slider-track-height: 6px;
  --mt-slider-track-radius: 0px;
  --mt-slider-progress: var(--t-g);
  --mt-slider-thumb-size: 8px;
  --mt-slider-thumb-bg: var(--t-g2);
  --mt-slider-thumb-bg-hover: #ffffff;
  --mt-slider-thumb-border: none;
  --mt-slider-thumb-radius: 0px;
  --mt-slider-thumb-shadow: none;
}
.mt-volume {
  --mt-slider-track: rgba(61, 255, 122, 0.18);
  --mt-slider-track-height: 3px;
  --mt-slider-track-radius: 0px;
  --mt-slider-progress: var(--t-gdim);
  --mt-slider-thumb-size: 7px;
  --mt-slider-thumb-bg: var(--t-g);
  --mt-slider-thumb-bg-hover: var(--t-g2);
  --mt-slider-thumb-border: none;
  --mt-slider-thumb-radius: 0px;
  --mt-slider-thumb-shadow: none;
}

/* the screen */
.mt-player {
  container-type: size;
  padding: 44px 12px 12px;
  background: radial-gradient(ellipse at 50% 30%, #0a1a10 0%, var(--t-bg) 75%);
  border: 1.5px dashed var(--t-g);
  border-radius: 0;
  color: var(--t-g);
  font-family: 'JetBrains Mono', monospace;
  box-shadow: 0 0 14px rgba(61, 255, 122, 0.22);
  backdrop-filter: none;
}
.mt-player * { font-family: inherit; }
.mt-player i { font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome; }

#moodtube-mini-player, #moodtube-mini-player *, #mt-settings-modal, #mt-settings-modal *, .mt-fab, .mt-fab *, .mt-pl-modal, .mt-pl-modal *, #moodtube-dock, #moodtube-dock * {
  text-shadow: none;
}

/* dashed rule under the header */
.mt-slot-bg::before {
  content: '';
  position: absolute;
  left: 12px;
  right: 12px;
  top: 36px;
  border-top: 1px dashed var(--t-gd);
}

.mt-player-header { top: 11px; left: 14px; right: 92px; display: flex; align-items: center; gap: 8px; }
.mt-player-header-title { font-family: 'Silkscreen', 'JetBrains Mono', monospace; font-size: 15px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: var(--t-g); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mt-player-status { font-size: 9px; color: var(--t-gdim); opacity: 1; white-space: nowrap; }
.mt-player-status::before { content: '['; }
.mt-player-status::after { content: ']'; }

.mt-window-btn {
  top: 11px;
  width: 20px;
  height: 20px;
  font-size: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  line-height: 1;
  box-sizing: border-box;
  color: var(--t-g);
  cursor: pointer;
  transition: color 0.15s;
}
.mt-window-btn:hover { color: #fff; }
.mt-btn-search.mt-is-open { color: #fff !important; }

.mt-player-body { gap: 7px; align-items: stretch; justify-content: flex-start; }
.mt-player-body::before {
  content: 'me@mood:~$ now_playing';
  order: 0;
  font-size: 10.5px;
  color: var(--t-g2);
}
.mt-player-body::after {
  content: 'me@mood:~$ _';
  order: 6;
  margin-top: auto;
  font-size: 10.5px;
  color: var(--t-gdim);
}

/* dot-matrix cover */
.mt-cover {
  order: 1;
  width: 100%;
  height: 92px;
  border-radius: 0;
  border: 1.5px dashed var(--t-g);
  background: var(--t-bg2);
  box-shadow: none;
  flex-shrink: 0;
}
img.mt-cover-img {
  border-radius: 0;
  object-fit: cover;
  filter: grayscale(1) contrast(1.35) brightness(1.1);
  -webkit-mask: radial-gradient(circle, #000 0, #000 1.4px, transparent 1.9px) 0 0 / 5px 5px;
  mask: radial-gradient(circle, #000 0, #000 1.4px, transparent 1.9px) 0 0 / 5px 5px;
}
.mt-slot-cover { border-radius: 0; background: var(--t-g); mix-blend-mode: multiply; }
.mt-slot-cover-bg { border-radius: 0; background: radial-gradient(var(--t-g) 1px, transparent 1.4px) 0 0 / 5px 5px; opacity: 0.35; }
.mt-cover-hole { display: none; }
.mt-cover::after {
  content: 'cover.img';
  position: absolute;
  z-index: 3;
  right: 4px;
  bottom: 2px;
  padding: 0 4px;
  font-size: 9px;
  color: var(--t-g2);
  background: var(--t-bg);
}

.mt-track-info { order: 2; align-items: flex-start; text-align: left; padding: 0 22px 0 0; }
#moodtube-mini-player .mt-track-title {
  font-family: 'VT323', 'JetBrains Mono', monospace;
  font-size: 22px;
  font-weight: 400;
  line-height: 1;
  letter-spacing: 0.01em;
  color: var(--t-g2);
  margin-bottom: 3px;
}
#moodtube-mini-player .mt-track-title::before { content: '> '; }
.mt-track-subtitle { font-size: 10px; font-weight: 400; color: var(--t-g); opacity: 0.75; }
.mt-track-subtitle::before { content: 'artist: '; }
.mt-btn-favorite {
  top: 2px;
  right: 0;
  width: 20px;
  height: 20px;
  padding: 0;
  background: none;
  border: none;
  font-size: 13px;
  color: var(--t-gdim);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.mt-btn-favorite:hover { color: #fff; }
.mt-btn-favorite.mt-is-active { color: var(--t-g2); }

/* progress as [ 0:42 ======== 3:14 ] */
.mt-progress { order: 3; gap: 5px; margin-top: 0; }
.mt-progress::before { content: '['; color: var(--t-gdim); font-size: 12px; }
.mt-progress::after { content: ']'; order: 10; color: var(--t-gdim); font-size: 12px; }
.mt-time-current, .mt-time-total { font-size: 9.5px; font-weight: 400; color: var(--t-g2); min-width: 24px; }

/* bracket buttons */
.mt-controls { order: 4; gap: 5px; justify-content: flex-start; flex-wrap: nowrap; }
.mt-controls > .mt-btn, .mt-controls > #moodtube-btn-playpause {
  width: auto;
  height: 26px;
  min-width: 0;
  padding: 0 6px;
  font-size: 0;
  line-height: 1;
  box-sizing: border-box;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 0;
  background: transparent;
  border: 1px solid var(--t-g);
  color: var(--t-g);
  cursor: pointer;
  transition: background-color 0.12s, color 0.12s;
}
.mt-controls > .mt-btn::before, .mt-controls > #moodtube-btn-playpause::before {
  font-family: 'JetBrains Mono', monospace;
  font-weight: 700;
  font-size: 11px;
  letter-spacing: 0;
  white-space: pre;
}
.mt-controls > .mt-btn-queue::before { content: '[=]'; }
.mt-controls > .mt-btn-prev::before { content: '[|<]'; }
.mt-controls > .mt-btn-next::before { content: '[>|]'; }
.mt-controls > #moodtube-btn-playpause::before { content: '[ > ]'; }
.mt-controls > #moodtube-btn-playpause.fa-pause::before { content: '[ || ]'; }
.mt-controls > .mt-btn-ai::before { content: '[ai]'; }
.mt-controls > .mt-btn-ai > * { display: none; }
.mt-controls > .mt-btn:hover { background: var(--t-g); color: var(--t-dark); }
.mt-controls > #moodtube-btn-playpause { background: var(--t-g); color: var(--t-dark); }
.mt-controls > #moodtube-btn-playpause:hover { background: var(--t-g2); border-color: var(--t-g2); }
.mt-controls > .mt-btn.mt-btn-ai.mt-is-busy { background: var(--t-g); color: var(--t-dark); animation: mt-tm-blink 0.9s steps(2) infinite; }
@keyframes mt-tm-blink { 50% { opacity: 0.45; } }

.mt-volume { order: 5; gap: 6px; width: 100%; }
.mt-volume-icon, .mt-volume-low, .mt-volume-high { font-size: 10px; color: var(--t-gdim); }

/* the cat: decor layer, bottom right. Eyes blink while playing, closed otherwise */
.mt-slot-decor::after {
  content: '  /\\___/\\ \A (  o o  )\A (  =^=  )\A  (")_(")~';
  white-space: pre;
  position: absolute;
  right: 12px;
  bottom: 12px;
  font-size: 9px;
  font-weight: 700;
  line-height: 1.05;
  color: var(--t-g);
}
.mt-player.mt-is-paused .mt-slot-decor::after,
.mt-player.mt-is-idle .mt-slot-decor::after { content: '  /\\___/\\ \A (  - -  )\A (  =^=  )\A  (")_(")~'; }
.mt-player.mt-is-playing .mt-slot-decor::after { animation: mt-tm-cat 5s steps(1) infinite; }
@keyframes mt-tm-cat {
  0%, 90%, 100% { content: '  /\\___/\\ \A (  o o  )\A (  =^=  )\A  (")_(")~'; }
  93%, 97% { content: '  /\\___/\\ \A (  - -  )\A (  =^=  )\A  (")_(")~'; }
}

/* panels: a log */
.mt-panel {
  background: var(--t-bg);
  color: var(--t-g);
  padding-top: 44px;
  border-radius: 0;
}
.mt-panel-header { border-bottom: 1px dashed var(--t-gd); padding-bottom: 6px; }
.mt-panel-header-left { margin-right: 20px; }
.mt-panel-title { font-family: 'Silkscreen', 'JetBrains Mono', monospace; font-size: 12px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--t-g); }
.mt-panel-queue .mt-panel-title { font-size: 0; }
.mt-panel-queue .mt-panel-title::before { content: 'QUEUE.LOG'; font-size: 12px; }
.mt-panel-close { color: var(--t-g); }
.mt-panel-close:hover { color: #fff; }
.mt-panel-queue::before, .mt-panel-queue::after, .mt-panel-playlists::before { pointer-events: none; position: absolute; }
.mt-panel-queue::before { content: 'me@mood:~$ next? [ y / n ]'; left: 15px; bottom: 14px; font-size: 10px; color: var(--t-gdim); }
.mt-panel-queue::after { content: '  /\\_/\\ \A ( -.- )  zzz\A  > ^ <'; white-space: pre; right: 15px; bottom: 36px; font-size: 9px; font-weight: 700; line-height: 1.05; color: var(--t-g); }
.mt-panel-queue .mt-panel-list { counter-reset: mtq; padding-bottom: 56px; }

.mt-queue-item { counter-increment: mtq; padding: 3px 4px; margin-bottom: 1px; border-radius: 0; background: transparent; border: 1px solid transparent; }
.mt-queue-item::before { content: counter(mtq, decimal-leading-zero); flex-shrink: 0; margin-right: 4px; font-size: 11px; color: var(--t-gdim); }
.mt-queue-item:hover { background: rgba(61, 255, 122, 0.1); }
.mt-queue-item.mt-is-current { background: var(--t-g); border-color: var(--t-g); }
.mt-queue-item.mt-is-current::before { content: '>' counter(mtq, decimal-leading-zero); color: var(--t-dark); }
.mt-queue-item.mt-is-current .mt-queue-title, .mt-queue-item.mt-is-current .mt-queue-now { color: var(--t-dark); }
.mt-queue-thumb { display: none; }
.mt-queue-title { color: var(--t-g); font-size: 11px; }
.mt-queue-now { color: var(--t-g2); }
.mt-queue-add { color: var(--t-g); }
.mt-queue-add:hover { color: #fff; }
.mt-queue-item.mt-is-current .mt-queue-add, .mt-queue-item.mt-is-current .mt-queue-dislike { color: var(--t-dark); }
.mt-queue-dislike { background-color: var(--t-gdim); }
.mt-queue-dislike:hover { background-color: #fff; }
.mt-queue-empty { color: var(--t-gdim); }

.mt-pl-tabs { border-bottom: 1px dashed var(--t-gd); gap: 6px; }
.mt-pl-tab { font-size: 10px; font-weight: 700; color: var(--t-g); background: transparent; border: 1px solid var(--t-g); border-radius: 0; }
.mt-pl-tab.mt-is-active { background: var(--t-g); border-color: var(--t-g); color: var(--t-dark); }
.mt-playlist-item { border-radius: 0; border-bottom: 1px dashed var(--t-line2); }
.mt-playlist-item:hover { background: rgba(61, 255, 122, 0.1); }
.mt-playlist-title { color: var(--t-g2); font-weight: 700; }
.mt-pl-count { color: var(--t-gdim); }
.mt-pl-cover { border-radius: 0; filter: grayscale(1) contrast(1.2); }
.mt-pl-tool { background: transparent; color: var(--t-g); border: 1px solid var(--t-g); border-radius: 0; }
.mt-pl-tool.mt-pl-play, .mt-pl-tool:hover { background: var(--t-g); border-color: var(--t-g); color: var(--t-dark); }

#moodtube-search-input { background: var(--t-bg2); color: var(--t-g2); border: 1px dashed var(--t-g); border-radius: 0; }
#moodtube-search-go { background: var(--t-g); color: var(--t-dark); border: none; border-radius: 0; font-weight: 700; }
#moodtube-search-go:hover { background: var(--t-g2); }

/* floating button, also when docked next to the input */
.mt-fab, .mt-fab.mt-fab-docked {
  background: var(--t-bg);
  border: 1.5px dashed var(--t-g);
  border-radius: 0;
  color: var(--t-g);
  box-shadow: 0 0 10px rgba(61, 255, 122, 0.3);
}
.mt-fab:hover, .mt-fab.mt-fab-docked:hover { background: var(--t-g); color: var(--t-dark); }

.mt-pl-modal-box { background: var(--t-bg); color: var(--t-g); border: 1.5px dashed var(--t-g); border-radius: 0; box-shadow: 0 0 24px rgba(61, 255, 122, 0.18); }
.mt-pl-modal-track { color: var(--t-g2); font-weight: 700; }
.mt-pl-option { color: var(--t-g); border: 1px dashed var(--t-line); border-radius: 0; background: transparent; }
.mt-pl-option:hover { background: rgba(61, 255, 122, 0.12); border-color: var(--t-g); }
.mt-pl-option.mt-is-added { background: var(--t-g); color: var(--t-dark); border-color: var(--t-g); }

/* settings */
#mt-settings-modal .mt-flex-container {
  background: var(--t-bg);
  color: var(--t-g);
  border: 1.5px dashed var(--t-g);
  border-radius: 0;
  box-shadow: 0 0 24px rgba(61, 255, 122, 0.18);
  font-family: 'JetBrains Mono', monospace;
}
#mt-settings-modal .mt-header h3 { font-family: 'Silkscreen', 'JetBrains Mono', monospace; font-weight: 700; font-size: 1.1em; letter-spacing: 0.1em; text-transform: uppercase; color: var(--t-g); }
#mt-settings-modal .mt-close { color: var(--t-g); }
#mt-settings-modal .mt-close:hover { color: #fff; }
#mt-settings-modal .mt-subpanel { background: rgba(61, 255, 122, 0.04); border: 1px dashed var(--t-line); border-radius: 0; }
#mt-settings-modal .mt-btn-test {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: var(--t-g);
  color: var(--t-dark);
  border: none;
  border-radius: 0;
  padding: 8px 14px;
  font-weight: 700;
  cursor: pointer;
}
#mt-settings-modal .mt-btn-test:hover { background: var(--t-g2); }
.mt-tag, .mt-genre-tag, .mt-mood-tag, .mt-scenario-tag { background: transparent; border: 1px solid var(--t-line); color: var(--t-g); border-radius: 0; padding: 4px 10px; }
.mt-tag:hover, .mt-genre-tag:hover, .mt-mood-tag:hover, .mt-scenario-tag:hover { border-color: var(--t-g); color: var(--t-g2); }
.mt-tag.active, .mt-genre-tag.active, .mt-mood-tag.active, .mt-scenario-tag.active { background: var(--t-g); border-color: var(--t-g); color: var(--t-dark); font-weight: 700; }

.mt-player ::-webkit-scrollbar, #mt-settings-modal ::-webkit-scrollbar, .mt-pl-modal-box ::-webkit-scrollbar { width: 5px; height: 5px; }
.mt-player ::-webkit-scrollbar-track, #mt-settings-modal ::-webkit-scrollbar-track, .mt-pl-modal-box ::-webkit-scrollbar-track { background: rgba(61, 255, 122, 0.06); }
.mt-player ::-webkit-scrollbar-thumb, #mt-settings-modal ::-webkit-scrollbar-thumb, .mt-pl-modal-box ::-webkit-scrollbar-thumb { background: var(--t-g); border-radius: 0; }

/* sizes and modes */
@container (max-width: 640px) { .mt-player.moodtube-row-layout .mt-volume { display: none; } }

.mt-player.moodtube-row-layout#moodtube-mini-player { padding: 44px 12px 12px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-player-body { flex-direction: row; align-items: center; justify-content: flex-start; gap: 12px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-player-body::before,
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-player-body::after { display: none; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-cover { width: 72px; height: 56px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-cover::after { display: none; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-track-info { min-width: 120px; max-width: 190px; flex: 0 1 170px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-progress { flex: 1 1 130px; min-width: 120px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-controls { flex-shrink: 0; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-volume { width: 76px; flex-shrink: 0; }

@container (max-height: 250px) {
  .mt-player:not(.moodtube-row-layout) .mt-player-body::before,
  .mt-player:not(.moodtube-row-layout) .mt-player-body::after { display: none; }
  .mt-player:not(.moodtube-row-layout) .mt-cover { height: 64px; }
  .mt-slot-decor::after { display: none; }
}
@container (max-width: 200px) {
  .mt-slot-decor::after { display: none; }
  .mt-player .mt-controls { gap: 3px; }
  .mt-player .mt-controls > .mt-btn, .mt-player .mt-controls > #moodtube-btn-playpause { padding: 0 4px; }
  .mt-player .mt-controls > .mt-btn::before, .mt-player .mt-controls > #moodtube-btn-playpause::before { font-size: 10px; }
}
@container (max-height: 150px) { .mt-slot-decor::after { display: none; } }

/* under the tavern header */
#moodtube-mini-player.mt-player-docked { background: radial-gradient(ellipse at 50% 30%, #0a1a10 0%, var(--t-bg) 75%); }

/* dock strip */
#moodtube-dock { background: var(--t-bg); border-bottom: 1px dashed var(--t-g); }
#moodtube-dock .mt-dock-title { font-family: 'VT323', 'JetBrains Mono', monospace; font-weight: 400; font-size: 19px; line-height: 1; color: var(--t-g2); }
#moodtube-dock .mt-dock-subtitle { font-family: 'JetBrains Mono', monospace; font-size: 9px; color: var(--t-g); opacity: 0.75; }
#moodtube-dock .mt-dock-inner .mt-dock-cover { border: 1px solid var(--t-g); }
#moodtube-dock .mt-dock-cover-img { filter: grayscale(1) contrast(1.3); }

/* ===== Dock bar (strip under the tavern header) [auto] ===== */
#moodtube-dock {
  font-family: 'JetBrains Mono', monospace;
  --mt-dock-cover-radius: 0;
}
#moodtube-dock, #moodtube-dock * { text-shadow: none; }
#moodtube-dock .mt-dock-cover { border-width: 1.5px; }
#moodtube-dock .mt-dock-controls { gap: 6px; }
#moodtube-dock .mt-dock-btn {
  width: 28px; height: 28px; padding: 0; box-sizing: border-box; line-height: 1; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; border-radius: 0;
  font-size: 12px; color: var(--mt-text);
  background: color-mix(in srgb, var(--mt-accent) 12%, transparent);
  transform: none; transition: background-color 0.2s;
}
#moodtube-dock .mt-dock-btn:hover { transform: none; color: var(--mt-text); background: color-mix(in srgb, var(--mt-accent) 28%, transparent); }
#moodtube-dock .mt-dock-play {
  width: 34px; height: 34px; font-size: 14px;
  background: var(--mt-accent); color: var(--mt-text-on-accent, #ffffff);
}
#moodtube-dock .mt-dock-play:hover { background: var(--mt-accent-hover, var(--mt-accent)); color: var(--mt-text-on-accent, #ffffff); }
#moodtube-dock .mt-dock-play.fa-play { padding-left: 2px; }
#moodtube-dock .mt-dock-fav, #moodtube-dock .mt-dock-ai, #moodtube-dock .mt-dock-queue { color: var(--mt-text); }
#moodtube-dock .mt-dock-fav.mt-is-active, #moodtube-dock .mt-dock-ai.mt-is-busy { color: var(--mt-accent); }
#moodtube-dock .mt-dock-expand, #moodtube-dock .mt-dock-close { color: var(--mt-text-dim, var(--mt-text)); }
#moodtube-dock .mt-dock-queue.mt-is-open, #moodtube-dock .mt-dock-expand.mt-is-open {
  color: var(--mt-text); text-shadow: none; background: color-mix(in srgb, var(--mt-accent) 30%, transparent);
}
#moodtube-dock .mt-dock-progress { height: 3px; }
@media (max-width: 420px) {
  #moodtube-dock .mt-dock-inner { gap: 6px; padding-left: 8px; padding-right: 8px; }
  #moodtube-dock .mt-dock-controls { gap: 3px; }
  #moodtube-dock .mt-dock-btn { width: 24px; height: 24px; font-size: 11px; }
  #moodtube-dock .mt-dock-play { width: 28px; height: 28px; font-size: 12px; }
}
/* ===== /Dock bar ===== */
/* == lyrics button == the fourth window button, in line with search / settings / close */
.mt-player .mt-lyrics-body { scrollbar-width: none; }
.mt-player .mt-lyrics-body::-webkit-scrollbar { display: none; width: 0; }
/* == /lyrics == */
/* == window buttons == 28px touch targets, evenly spaced, in line with the header */
#moodtube-mini-player .mt-window-btn { width: 28px; height: 28px; min-width: 28px; padding: 0; box-sizing: border-box; display: flex; align-items: center; justify-content: center; line-height: 1; top: 8px; font-size: 14px; }
#moodtube-mini-player .mt-window-btn.mt-btn-close { right: 12px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-settings { right: 44px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-search { right: 76px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-lyrics { right: 108px; left: auto; }
#moodtube-mini-player .mt-player-header-title { font-size: 12px; letter-spacing: 1px; }
/* == /window buttons == */
